/* eslint-disable import/no-unresolved -- runs inside the Forest app, which provides these */
/* eslint-env browser */
/**
 * A feature explainer's workspace Custom component (generated by charts/features.js
 * once per feature, with that feature's content written in). Its only way out is the Hub, plus
 * the buttons that open the place in the demo where the feature shows.
 */
import { action } from '@ember/object';
import { inject as service } from '@ember/service';
import Component from '@glimmer/component';
import { tracked } from '@glimmer/tracking';

// Written at build time (scripts/build-public.js): the feature, its facts, the Hub's workspace id.
const FEATURE = {"hubId":"30b652d1-5f0e-4556-8a96-4863f009eb85","workspaceId":"8da7be9d-4b5c-4916-8e38-36c0f1a6004d","position":5,"total":12,"key":"smart-actions","icon":"⚡","name":"Smart Actions","promise":"Your business operations as buttons: a form, your code runs, a card shows what it did.","hubWhere":"MLRO desk: File SAR. Disputes desk: Route dispute, File with network.","what":["A Smart Action is a button on a record that runs your own code in the agent: approve a transfer, file a SAR, block a card, call a provider.","It can ask for input first, with a form that adapts as you fill it, and finish with a result card that shows what changed.","Sensitive ones can need a second person: with approvals on, the action waits until someone allowed to approve it says yes."],"facts":[{"value":73,"label":"Smart Actions in this demo"},{"value":26,"label":"of them as buttons on the desks"}],"setup":["A developer declares it in the agent: collection.addAction(\"Route dispute\", { scope, form, execute }).","The form fields go in “form”; the result card is the HTML the action returns.","In the Layout Editor, table settings, Actions tab: choose where the button shows and its color.","Approvals: Project settings, Roles, then per action “Require approval” and who may approve. Requests land in Collaboration, Approval Workflow."],"docs":"https://docs.forest.app/product/execute/actions.md","art":"actions","buttons":[{"label":"Open the Disputes desk","workspaceId":"9d9fa26f-31c8-4c99-874e-2154843f6ba5","collection":null},{"label":"Open the MLRO desk","workspaceId":"a20b591a-fc4d-4d01-8c85-559d571b1c29","collection":null}]}

const UUID = /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi;

/** "records.customers" in the chart's answer, or undefined. */
const pick = (facts, dotted) =>
  dotted.split('.').reduce((value, key) => (value == null ? undefined : value[key]), facts);
const format = value => (typeof value === 'number' ? value.toLocaleString('en-GB') : value);

export default class extends Component {
  @service lianaServerFetch;

  @service router;

  @tracked liveFacts = null;

  @tracked liveStatus = 'loading';

  feature = FEATURE;

  // One flag per illustration: the template shows the one whose flag is set.
  art = { [FEATURE.art]: true };

  steps = FEATURE.setup.map((text, i) => ({ number: i + 1, text }));

  hasFacts = FEATURE.facts.length > 0;

  constructor(...args) {
    super(...args);
    if (FEATURE.facts.some(f => f.live)) this.loadFacts();
    else this.liveStatus = 'none';
  }

  async loadFacts() {
    try {
      const response = await this.lianaServerFetch.fetch('/forest/_charts/feature_facts', {});
      if (!response.ok) throw new Error(`feature_facts: ${response.status}`);
      this.liveFacts = await response.json();
      this.liveStatus = 'ok';
    } catch (error) {
      this.liveStatus = 'failed';
    }
  }

  /** Static facts as they are; live ones once the chart answers ("…" until then, "–" if not). */
  get facts() {
    return FEATURE.facts.map(f => {
      if (!f.live) return { label: f.label, value: format(f.value), live: false };
      const value = this.liveFacts ? pick(this.liveFacts, f.live) : undefined;
      let shown = '…';
      if (value !== undefined) shown = format(value);
      else if (this.liveStatus === 'failed' || this.liveFacts) shown = '–';

      return { label: f.label, value: shown, live: true };
    });
  }

  get liveNote() {
    if (this.liveStatus === 'ok') return 'Live from this demo’s data.';
    if (this.liveStatus === 'failed') return 'Live figures unavailable: is the agent running?';
    if (this.liveStatus === 'loading') return 'Counting…';

    return '';
  }

  /** The current url with the workspace id swapped: no need to know Forest's url scheme. */
  static workspacePath(workspaceId) {
    const path = window.location.pathname;
    const ids = path.match(UUID) || [];
    const current =
      FEATURE.workspaceId && path.includes(FEATURE.workspaceId)
        ? FEATURE.workspaceId
        : ids[ids.length - 1];
    if (!current) return null;
    const at = path.lastIndexOf(current);

    return `${path.slice(0, at)}${workspaceId}`;
  }

  /** A table's list, assuming /<project>/<environment>/<team>/data/<table>/index. */
  static tablePath(collection) {
    const [project, environment, team] = window.location.pathname.split('/').filter(Boolean);

    return `/${project}/${environment}/${team}/data/${collection}/index`;
  }

  /** Inside the app when the router knows the url, else a full page load. */
  go(path) {
    if (!path) return;

    try {
      const transition = this.router.transitionTo(path);
      transition?.catch?.(error => {
        if (error?.name !== 'TransitionAborted') window.location.assign(path);
      });
    } catch (error) {
      window.location.assign(path);
    }
  }

  @action
  openHub() {
    this.go(this.constructor.workspacePath(FEATURE.hubId));
  }

  @action
  open(button) {
    if (button.workspaceId) this.go(this.constructor.workspacePath(button.workspaceId));
    else if (button.collection) this.go(this.constructor.tablePath(button.collection));
  }
}
